                    "priorB",
                    "delta",
                    "gammaE",
                    "effInterim",
                    "futility",
                    "gammaF")))
            self$add(jmvcore::Image$new(
                options=options,
                name="bfPlot",
                title="Bayes factor path",
                width=550,
                height=420,
                renderFun=".plotBF",
                visible="(probPlot && model:bf)",
                clearWith=list(
                    "dep",
                    "group",
                    "model",
                    "bfSamples",
                    "mu0",
                    "rScale",
                    "bfK",
                    "bfNMin",
                    "bfNMax")))
            self$add(jmvcore::Image$new(
                options=options,
                name="densityPlot",
                title="Prior and posterior",
                width=550,
                height=420,
                renderFun=".plotDensity",
                visible="(densityPlot && (model:normal || model:binary))",
                clearWith=list(
                    "lookN",
                    "estimate",
                    "se",
                    "xC",
                    "nC",
                    "xT",
                    "nT",
                    "model",
                    "nMax",
                    "arms",
                    "sigma",
                    "theta1",
                    "prior",
                    "priorMean",
                    "priorSD",
                    "pC",
                    "pT",
                    "priorA",
                    "priorB")))
            self$add(jmvcore::Image$new(
                options=options,
                name="ocPlot",
                title="Operating characteristics",
                width=550,
                height=500,
                renderFun=".plotOC",
                visible="(ocPlot && (model:normal || model:binary))",
                clearWith=list(
                    "model",
                    "nMax",
                    "nLooks",
                    "timing",
                    "arms",
                    "sigma",
                    "theta1",
                    "prior",
                    "priorMean",
                    "priorSD",
                    "pC",
                    "pT",
                    "bNMax",
                    "priorA",
                    "priorB",
                    "delta",
                    "gammaE",
                    "effInterim",
                    "futility",
                    "gammaF")))}))

bayesmonBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "bayesmonBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "jmsequential",
                name = "bayesmon",
                version = c(0,5,0),
                options = options,
                results = bayesmonResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Bayesian Sequential Monitoring
#'
#' Bayesian monitoring rules at interim analyses: stop for efficacy when the 
#' posterior probability of an effect beyond a threshold is high, and for 
#' futility when the predictive probability of final success is low; normal 
#' approximation (estimate and standard error per look) or two arms with a 
#' binary outcome (beta-binomial). Sequential Bayes factor t-tests (JZS) on 
#' raw data. Frequentist operating characteristics, exact or simulated.
#' @param data .
#' @param lookN .
#' @param estimate .
#' @param se .
#' @param xC .
#' @param nC .
#' @param xT .
#' @param nT .
#' @param dep .
#' @param group .
#' @param model .
#' @param nMax .
#' @param nLooks .
#' @param timing .
#' @param arms .
#' @param sigma .
#' @param theta1 .
#' @param prior .
#' @param priorMean .
#' @param priorSD .
#' @param pC .
#' @param pT .
#' @param bNMax .
#' @param priorA .
#' @param priorB .
#' @param delta .
#' @param gammaE .
#' @param effInterim .
#' @param futility .
#' @param gammaF .
#' @param bfSamples .
#' @param mu0 .
#' @param rScale .
#' @param bfK .
#' @param bfNMin .
#' @param bfNMax .
#' @param d1 .
#' @param nsim .
#' @param seed .
#' @param level .
#' @param ocTable .
#' @param boundPlot .
#' @param probPlot .
#' @param densityPlot .
#' @param ocPlot .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$looks} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$oc} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bfDesign} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$monitor} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$monitorBin} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bfTest} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$boundPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$probPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$bfPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$densityPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$ocPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
bayesmon <- function(
    data,
    lookN = NULL,
    estimate = NULL,
    se = NULL,
    xC = NULL,
    nC = NULL,
    xT = NULL,
    nT = NULL,
    dep = NULL,
    group = NULL,
    model = "normal",
    nMax = 180,
    nLooks = 3,
    timing = "",
    arms = "two",
    sigma = 1,
    theta1 = 0.5,
    prior = "sceptical",
    priorMean = 0,
    priorSD = 1,
    pC = 0.3,
    pT = 0.5,
    bNMax = 60,
    priorA = 1,
    priorB = 1,
    delta = 0,
    gammaE = 0.975,
    effInterim = TRUE,
    futility = TRUE,
    gammaF = 0.1,
    bfSamples = "two",
    mu0 = 0,
    rScale = 0.707,
    bfK = 10,
    bfNMin = 10,
    bfNMax = 100,
    d1 = 0.5,
    nsim = 1000,
    seed = 1,
    level = 0.95,
    ocTable = TRUE,
    boundPlot = TRUE,
    probPlot = TRUE,
    densityPlot = FALSE,
    ocPlot = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("bayesmon requires jmvcore to be installed (restart may be required)")

    if ( ! missing(lookN)) lookN <- jmvcore::resolveQuo(jmvcore::enquo(lookN))
    if ( ! missing(estimate)) estimate <- jmvcore::resolveQuo(jmvcore::enquo(estimate))
    if ( ! missing(se)) se <- jmvcore::resolveQuo(jmvcore::enquo(se))
    if ( ! missing(xC)) xC <- jmvcore::resolveQuo(jmvcore::enquo(xC))
    if ( ! missing(nC)) nC <- jmvcore::resolveQuo(jmvcore::enquo(nC))
    if ( ! missing(xT)) xT <- jmvcore::resolveQuo(jmvcore::enquo(xT))
    if ( ! missing(nT)) nT <- jmvcore::resolveQuo(jmvcore::enquo(nT))
    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(lookN), lookN, NULL),
            `if`( ! missing(estimate), estimate, NULL),
            `if`( ! missing(se), se, NULL),
            `if`( ! missing(xC), xC, NULL),
            `if`( ! missing(nC), nC, NULL),
            `if`( ! missing(xT), xT, NULL),
            `if`( ! missing(nT), nT, NULL),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(group), group, NULL))

    for (v in group) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- bayesmonOptions$new(
        lookN = lookN,
        estimate = estimate,
        se = se,
        xC = xC,
        nC = nC,
        xT = xT,
        nT = nT,
        dep = dep,
        group = group,
        model = model,
        nMax = nMax,
        nLooks = nLooks,
        timing = timing,
        arms = arms,
        sigma = sigma,
        theta1 = theta1,
        prior = prior,
        priorMean = priorMean,
        priorSD = priorSD,
        pC = pC,
        pT = pT,
        bNMax = bNMax,
        priorA = priorA,
        priorB = priorB,
        delta = delta,
        gammaE = gammaE,
        effInterim = effInterim,
        futility = futility,
        gammaF = gammaF,
        bfSamples = bfSamples,
        mu0 = mu0,
        rScale = rScale,
        bfK = bfK,
        bfNMin = bfNMin,
        bfNMax = bfNMax,
        d1 = d1,
        nsim = nsim,
        seed = seed,
        level = level,
        ocTable = ocTable,
        boundPlot = boundPlot,
        probPlot = probPlot,
        densityPlot = densityPlot,
        ocPlot = ocPlot)

    analysis <- bayesmonClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

